type Session = {
  id: string; csrf: string; created: number; seen: number; phase: "preauth" | "auth"; user?: string;
  email?: string; code?: string; codeExpires?: number; codeUsed?: boolean; failures: number; locked?: number; enrollment?: Enrollment;
