}

/* Standards-compliant QR Model 2 encoder: Version 10, error correction L, byte mode, mask 0.
   The UTF-8 payload passed to this encoder is exactly the returned otpauth provisioning URI. */
function qr(payload){
 const bytes=new TextEncoder().encode(payload), size=57, dataCap=274;
 if(bytes.length>255||bytes.length>dataCap-3)return E("div",{class:"error",text:"QR code is too long. Use the copy button instead."});
 const bits=[];const put=(v,n)=>{for(let i=n-1;i>=0;i--)bits.push((v>>>i)&1)};put(4,4);put(bytes.length,16);bytes.forEach(b=>put(b,8));put(0,Math.min(4,dataCap*8-bits.length));while(bits.length%8)bits.push(0);
 const raw=[];for(let i=0;i<bits.length;i+=8)raw.push(bits.slice(i,i+8).reduce((a,b)=>a*2+b,0));let toggle=true;while(raw.length<dataCap){raw.push(toggle?236:17);toggle=!toggle}
 const exp=[],log=[];let x=1;for(let i=0;i<255;i++){exp[i]=x;log[x]=i;x<<=1;if(x&256)x^=285}for(let i=255;i<512;i++)exp[i]=exp[i-255];
 const mul=(a,b)=>a&&b?exp[log[a]+log[b]]:0;let gen=[1];for(let i=0;i<18;i++){const next=Array(gen.length+1).fill(0);for(let j=0;j<gen.length;j++){next[j]^=gen[j];next[j+1]^=mul(gen[j],exp[i])}gen=next}
 const rem=block=>{const out=Array(18).fill(0);for(const b of block){const f=b^out.shift();out.push(0);for(let j=0;j<18;j++)out[j]^=mul(gen[j+1],f)}return out};
 const lengths=[68,68,69,69], blocks=[];let at=0;for(const len of lengths){const b=raw.slice(at,at+len);at+=len;blocks.push(b)}
 const ecs=blocks.map(rem), words=[];for(let i=0;i<69;i++)for(const b of blocks)if(i<b.length)words.push(b[i]);for(let i=0;i<18;i++)for(const e of ecs)words.push(e[i]);
 const m=Array.from({length:size},()=>Array(size).fill(null));const set=(r,c,v)=>{if(r>=0&&c>=0&&r<size&&c<size)m[r][c]=v};
 const finder=(r,c)=>{for(let y=-1;y<=7;y++)for(let z=-1;z<=7;z++)set(r+y,c+z,y>=0&&y<=6&&z>=0&&z<=6&&(y===0||y===6||z===0||z===6||(y>=2&&y<=4&&z>=2&&z<=4)))};
 finder(0,0);finder(0,size-7);finder(size-7,0);
 for(const r of [6,28,50])for(const c of [6,28,50])if(m[r][c]===null){for(let y=-2;y<=2;y++)for(let z=-2;z<=2;z++)set(r+y,c+z,Math.max(Math.abs(y),Math.abs(z))!==1)}
 for(let i=8;i<size-8;i++){if(m[6][i]===null)set(6,i,i%2===0);if(m[i][6]===null)set(i,6,i%2===0)}
 let f=8;for(let i=0;i<10;i++)f=(f<<1)^((f>>>9)*0x537);f=((8<<10)|f)^0x5412;
 for(let i=0;i<15;i++){const v=((f>>>i)&1)===1;set(i<6?i:i<8?i+1:size-15+i,8,v);set(8,i<8?size-i-1:i<9?15-i:size-i,v)}set(size-8,8,true);
 let row=size-1,up=true,wi=0,bi=7;for(let col=size-1;col>0;col-=2){if(col===6)col--;for(;;){for(let c=0;c<2;c++){const cc=col-c;if(m[row][cc]===null){let v=wi<words.length?((words[wi]>>>bi)&1):0;if((row+cc)%2===0)v^=1;m[row][cc]!!v;if(--bi<0){wi++;bi=7}}}row+=up?-1:1;if(row<0||row>=size){row+=up?1:-1;up=!up;break}}}
 const box=E("div",{class:"qr",role:"img","aria-label":"Authenticator setup QR code"});box.style.gridTemplateColumns="repeat("+size+",1fr)";for(const line of m)for(const dark of line)box.append(E("span",{class:dark?"q":""}));return box;
}
function enrol(r){
 head(r,2);r.append(E("h1",{text:"Add the authenticator"}),E("p",{text:"In your authenticator app, add an account. Scan the QR code or copy the setup secret."}));status(r);
 r.append(E("button",{class:"secondary",type:"button","aria-expanded":String(S.showQR),onClick:()=>{S.showQR=!S.showQR;render()},text:S.showQR?"Hide QR code":"Show QR code"}));if(S.showQR)r.append(qr(S.uri));
 r.append(E("h2",{text:"Manual setup secret"}),E("button",{class:"secondary",type:"button","aria-expanded":String(S.showSecret),onClick:()=>{S.showSecret=!S.showSecret;render()},text:S.showSecret?"Hide setup secret":"Show setup secret"}));
 if(S.showSecret)r.append(E("div",{class:"secret",text:S.secret}),E("button",{class:"secondary",type:"button",onClick:()=>copy(S.secret,"The setup secret was copied."),text:"Copy setup secret"}));
 r.append(E("div",{class:"hint",text:"Demo test code: "+S.otp}));const input=field(r,"Authenticator code",{type:"text",inputmode:"numeric",autocomplete:"one-time-code",maxlength:"6",placeholder:"Example: 123456"});
 primary(r,"Confirm authenticator",async()=>{const x=await api("/api/mfa/confirm","POST",{otp:input.value.replace(/\\s/g,"")});if(!x.ok){S.error=x.message;return render()}S.mfa=true;S.secret=S.uri=S.otp="";S.notice="Authenticator confirmed. Now save your recovery codes.";S.error="";S.view="codes";render()});
 r.append(E("button",{class:"link",type:"button",onClick:()=>{S.view="home";render()},text:"Back"}));help(r);logs(r);
}
function replacementPrompt(r){
 if(!S.confirmReplace)return;
 r.append(E("div",{class:"error",role:"alert",text:"Generate new codes? All prior unused recovery codes will stop working."}));
 r.append(E("button",{class:"secondary",type:"button",onClick:()=>{S.confirmReplace=false;render()},text:"Keep current codes"}));
 primary(r,"Yes, replace all codes",async()=>{const x=await api("/api/mfa/backup/regenerate","POST",{confirm:true});if(!x.ok){S.error=x.message;S.confirmReplace=false;return render()}S.codes=x.codes;S.recoveryExists=true;S.showCodes=false;S.confirmReplace=false;log("Mock replacement recovery codes: "+x.codes.join(", "));S.notice="All old recovery codes stopped working. Save these new codes now.";S.error="";render()});
