/* QR requirement: ISO/IEC 18004 QR Model 2 Version 10-L encoder.
   Includes all reserved function areas, Version Information, correct V10 alignment
   positions, Reed-Solomon interleaving, and standard zig-zag data placement. */
function qr(payload){
 const version=10,size=57,dataCap=274,ecWords=18;
 const bytes=new TextEncoder().encode(payload);
 if(bytes.length>255||bytes.length>dataCap-3)return E("div",{class:"error",text:"QR code is too long. Use the copy button instead."});

 const bits=[],put=(v,n)=>{for(let i=n-1;i>=0;i--)bits.push((v>>>i)&1)};
 put(4,4);put(bytes.length,16);bytes.forEach(b=>put(b,8));
 put(0,Math.min(4,dataCap*8-bits.length));while(bits.length%8)bits.push(0);
 const raw=[];for(let i=0;i<bits.length;i+=8)raw.push(bits.slice(i,i+8).reduce((a,b)=>(a<<1)|b,0));
 for(let pad=0;raw.length<dataCap;pad^=1)raw.push(pad?0x11:0xec);

 const exp=[],log=[];let x=1;
 for(let i=0;i<255;i++){exp[i]=x;log[x]=i;x<<=1;if(x&0x100)x^=0x11d}
 for(let i=255;i<512;i++)exp[i]=exp[i-255];
 const mul=(a,b)=>a&&b?exp[log[a]+log[b]]:0;
 let gen=[1];
 for(let i=0;i<ecWords;i++){const next=Array(gen.length+1).fill(0);for(let j=0;j<gen.length;j++){next[j]^=gen[j];next[j+1]^=mul(gen[j],exp[i])}gen=next}
 const remainder=block=>{const out=Array(ecWords).fill(0);for(const byte of block){const factor=byte^out.shift();out.push(0);for(let j=0;j<ecWords;j++)out[j]^=mul(gen[j+1],factor)}return out};
 const blocks=[],lengths=[68,68,69,69];let offset=0;
 for(const len of lengths){blocks.push(raw.slice(offset,offset+len));offset+=len}
 const ecs=blocks.map(remainder),words=[];
 for(let i=0;i<69;i++)for(const block of blocks)if(i<block.length)words.push(block[i]);
 for(let i=0;i<ecWords;i++)for(const block of ecs)words.push(block[i]);

 const m=Array.from({length:size},()=>Array(size).fill(null));
 const set=(row,col,value)=>{if(row>=0&&col>=0&&row<size&&col<size)m[row][col]=!!value};
 const finder=(row,col)=>{for(let y=-1;y<=7;y++)for(let x=-1;x<=7;x++)set(row+y,col+x,y>=0&&y<=6&&x>=0&&x<=6&&(y===0||y===6||x===0||x===6||(y>=2&&y<=4&&x>=2&&x<=4)))};
 finder(0,0);finder(0,size-7);finder(size-7,0);

 /* Version 10 alignment centers: 6, 28, 50. Skip overlapping finder/timing areas. */
 for(const row of [6,28,50])for(const col of [6,28,50])if(m[row][col]===null){
   for(let y=-2;y<=2;y++)for(let x=-2;x<=2;x++)set(row+y,col+x,Math.max(Math.abs(y),Math.abs(x))!==1);
 }
 for(let i=8;i<size-8;i++){if(m[6][i]===null)set(6,i,i%2===0);if(m[i][6]===null)set(i,6,i%2===0)}

 const bch=(value,poly)=>{let v=value;const degree=Math.floor(Math.log2(poly));while(Math.floor(Math.log2(v))>=degree)v^=poly<<(Math.floor(Math.log2(v))-degree);return v};
 /* EC level L format bits: 01, with mask pattern 0. */
 const formatData=0b01000,format=((formatData<<10)|bch(formatData<<10,0x537))^0x5412;
 for(let i=0;i<15;i++){
   const dark=((format>>>i)&1)!==0;
   set(i<6?i:i<8?i+1:size-15+i,8,dark);
   set(8,i<8?size-i-1:i<9?15-i:14-i,dark);
 }
 set(size-8,8,true);

 /* Required Version Information for versions 7 through 40. */
 const versionInfo=(version<<12)|bch(version<<12,0x1f25);
 for(let i=0;i<18;i++){
   const dark=((versionInfo>>>i)&1)!==0, a=size-11+(i%3), b=Math.floor(i/3);
   set(b,a,dark);
   set(a,b,dark);
 }

 /* Two-column upward/downward data sweep. All functional modules above are reserved. */
 let row=size-1,up=true,word=0,bit=7;
 for(let col=size-1;col>0;col-=2){
   if(col===6)col--;
   for(;;){
     for(let dx=0;dx<2;dx++){
       const c=col-dx;
       if(m[row][c]===null){
         let dark=word<words.length?((words[word]>>>bit)&1):0;
         if((row+c)%2===0)dark^=1; /* mask 0 */
         m[row][c]=!!dark;
         if(--bit<0){word++;bit=7}
       }
     }
     row+=up?-1:1;
     if(row<0||row>=size){row+=up?1:-1;up=!up;break}
   }
 }
 const box=E("div",{class:"qr",role:"img","aria-label":"Authenticator setup QR code"});
 for(const line of m)for(const dark of line)box.append(E("span",{class:dark?"q":""}));
 return box;
}
